def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "neg": 3, "^": 4}

    def apply() -> bool:
        op = operators.pop()

        if op == "neg":
            values[-1] = -values[-1]
            return True

        b = values.pop()
        a = values.pop()

        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "^":
            if b < 0:
                return False
            result = pow(a, b)
        else:
            if b == 0:
                return False
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            result = quotient if op == "/" else a - b * quotient

        values.append(result)
        return True

    i = 0
    n = len(expr)
    expect_operand = True

    while i < n:
        char = expr[i]

        if char.isspace():
            i += 1
            continue

        if "0" <= char <= "9":
            value = 0
            while i < n and "0" <= expr[i] <= "9":
                value = value * 10 + ord(expr[i]) - ord("0")
                i += 1
            values.append(value)
            expect_operand = False
            continue

        if char == "(":
            operators.append(char)
            expect_operand = True
        elif char == ")":
            while operators[-1] != "(":
                if not apply():
                    return "error"
            operators.pop()
            expect_operand = False
        elif char == "-" and expect_operand:
            operators.append("neg")
        else:
            while operators and operators[-1] != "(":
                top = operators[-1]
                if precedence[top] < precedence[char]:
                    break
                if precedence[top] == precedence[char] and char == "^":
                    break
                if not apply():
                    return "error"
            operators.append(char)
            expect_operand = True

        i += 1

    while operators:
        if not apply():
            return "error"

    return values[0]
